package com.hoc.balancedflight.foundation.network;

import com.hoc.balancedflight.foundation.network.CustomNetworkMessage;
import net.minecraft.resources.ResourceLocation;
import net.minecraftforge.network.NetworkRegistry;
import net.minecraftforge.network.simple.SimpleChannel;

public class BalancedFlightNetwork {
    public static SimpleChannel INSTANCE;
    public static final String VERSION = "1.0";
    private static int ID;

    private static int nextID() {
        return ID++;
    }

    public static void registerMessage() {
        INSTANCE = NetworkRegistry.newSimpleChannel((ResourceLocation)ResourceLocation.fromNamespaceAndPath((String)"balancedflight", (String)"main_network"), () -> VERSION, VERSION::equals, VERSION::equals);
        INSTANCE.messageBuilder(CustomNetworkMessage.class, BalancedFlightNetwork.nextID()).encoder(CustomNetworkMessage::toBytes).decoder(CustomNetworkMessage::new).consumerNetworkThread(CustomNetworkMessage::handler).add();
    }

    static {
        ID = 0;
    }
}

